import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import cookieParser from "cookie-parser";
import { OAuth2Client } from "google-auth-library";
import jwt from "jsonwebtoken";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(cookieParser());

// Extract variables
const clientId = process.env.GOOGLE_CLIENT_ID;
const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
const sessionSecret = process.env.SESSION_SECRET || "default_secret_for_dev_only";

// Keep in mind auth callback redirect URIs must be absolute
const getRedirectUri = (req: express.Request) => {
  const host = req.headers['x-forwarded-host'] || req.headers.host;
  const proto = req.headers['x-forwarded-proto'] || req.protocol;
  // If APP_URL is provided, use that, otherwise guess from headers
  const base = process.env.APP_URL || `${proto}://${host}`;
  return `${base}/api/auth/callback`;
};

// API routes FIRST
app.get("/api/health", (req, res) => {
  res.json({ status: "ok" });
});

app.get('/api/auth/url', (req, res) => {
  if (!clientId || !clientSecret) {
    return res.status(500).json({ error: "Google OAuth credentials not configured." });
  }

  const redirectUri = getRedirectUri(req);
  const oauth2Client = new OAuth2Client(clientId, clientSecret, redirectUri);

  const authUrl = oauth2Client.generateAuthUrl({
    access_type: 'offline',
    scope: [
      'https://www.googleapis.com/auth/userinfo.profile',
      'https://www.googleapis.com/auth/userinfo.email',
    ],
    prompt: 'consent'
  });

  res.json({ url: authUrl });
});

app.get('/api/auth/callback', async (req, res) => {
  const { code } = req.query;

  if (!code || typeof code !== 'string') {
    return res.status(400).send("Invalid code");
  }

  if (!clientId || !clientSecret) {
    return res.status(500).send("OAuth not configured");
  }

  try {
    const redirectUri = getRedirectUri(req);
    const oauth2Client = new OAuth2Client(clientId, clientSecret, redirectUri);
    
    // Exchange the code for an access token
    const { tokens } = await oauth2Client.getToken(code);
    oauth2Client.setCredentials(tokens);

    // Fetch user info
    const oauth2 = await oauth2Client.request({ url: 'https://www.googleapis.com/oauth2/v2/userinfo' });
    const userData = oauth2.data;

    // Create a JWT session token to persist in cookie
    const token = jwt.sign(userData as any, sessionSecret, { expiresIn: '7d' });

    res.cookie('token', token, {
      secure: true,
      sameSite: 'none',
      httpOnly: true,
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    // Send success message to parent window and close popup
    res.send(`
      <html>
        <body>
          <script>
            if (window.opener) {
              window.opener.postMessage({ type: 'OAUTH_AUTH_SUCCESS' }, '*');
              window.close();
            } else {
              window.location.href = '/';
            }
          </script>
          <p>Authentication successful. This window should close automatically.</p>
        </body>
      </html>
    `);
  } catch (err: any) {
    console.error("Error during authentication callback:", err);
    res.status(500).send(`Authentication failed: ${err.message}`);
  }
});

app.get('/api/auth/user', (req, res) => {
  const token = req.cookies.token;
  if (!token) {
    return res.status(401).json({ user: null });
  }

  try {
    const decoded = jwt.verify(token, sessionSecret);
    res.json({ user: decoded });
  } catch (err) {
    res.status(401).json({ user: null });
  }
});

app.post('/api/auth/logout', (req, res) => {
  res.clearCookie('token', {
    secure: true,
    sameSite: 'none',
    httpOnly: true
  });
  res.json({ success: true });
});

async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
